import json
from pathlib import Path
ROOT=Path(__file__).parent
css=(ROOT/'src/styles.css').read_text().replace('@import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@500;600&display=swap\');','')
data=json.load(open(ROOT/'public/data/market.json'))
geo=json.load(open(ROOT/'public/data/map.json'))
script=r'''
const DATA=__DATA__;const GEO=__GEO__;
const months=DATA.monthly,last=months[months.length-1],forecast=DATA.forecast;
const fmt=n=>Math.round(n).toLocaleString('en-MY');const pct=(n,d=2)=>Number(n).toFixed(d)+'%';
let mode='registrations',range='3Y',hover=null,city='Kuala Lumpur',mapZoom=1;
const icons={up:'<path d="M5 19 19 5M9 5h10v10"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',chart:'<path d="M4 19h16M5 15l5-5 4 3 5-7M15 6h4v4"/>',moon:'<path d="M20.5 14.5A8.5 8.5 0 0 1 9.5 3.5a8.5 8.5 0 1 0 11 11Z"/>',download:'<path d="M12 3v12m0 0 4-4m-4 4-4-4M4 17v4h16v-4"/>',database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-8v.2"/>'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><g opacity=".52">${icons[name]||icons.up}</g><g opacity=".94">${icons[name]||icons.up}</g></svg>`;
function graph(){const d=range==='1Y'?months.slice(-12):range==='3Y'?months.slice(-36):months;const keys=mode==='share'?['evShare','hybridShare']:['ev','hybrid'];const maxV=Math.max(...d.flatMap(r=>keys.map(k=>r[k])));const maxY=Math.ceil(maxV/(mode==='share'?2:2000)*1.16)*(mode==='share'?2:2000);const x=i=>52+920*i/(d.length-1),y=v=>260-v/maxY*242;const lin=(arr)=>arr.map((r,i)=>(i?'L':'M')+x(i).toFixed(2)+','+y(r).toFixed(2)).join(' ');let i=(hover===null?d.length-1:Math.min(hover,d.length-1));let val=d[i];document.getElementById('real-chart').innerHTML=`<svg viewBox="0 0 1000 305" preserveAspectRatio="none">${[0,.25,.5,.75,1].map(v=>`<line x1="52" y1="${y(maxY*v)}" x2="972" y2="${y(maxY*v)}" class="chart-grid"/><text x="39" y="${y(maxY*v)+4}" text-anchor="end" class="axis-label">${mode==='share'?(maxY*v).toFixed(0)+'%':(maxY*v/1000).toFixed(0)+'k'}</text>`).join('')}${[0,.2,.4,.6,.8,1].map(r=>{let j=Math.min(d.length-1,Math.round((d.length-1)*r));return `<text class="axis-label" x="${x(j)}" y="287" text-anchor="middle">${d[j].date.slice(2)}</text>`}).join('')}<path d="${lin(d.map(z=>z[keys[0]]))}" stroke="#9ceb19" stroke-width="3.6" fill="none" stroke-linecap="round"/><path d="${lin(d.map(z=>z[keys[1]]))}" stroke="#747a79" stroke-width="2.8" fill="none" stroke-linecap="round"/><line x1="${x(i)}" x2="${x(i)}" y1="18" y2="260" stroke="currentColor" opacity=".18" stroke-dasharray="4 5"/><circle cx="${x(i)}" cy="${y(val[keys[0]])}" r="6" fill="#aaff19" stroke="var(--card)" stroke-width="3"/><circle cx="${x(i)}" cy="${y(val[keys[1]])}" r="6" fill="#747a79" stroke="var(--card)" stroke-width="3"/><rect id="chart-hot" x="52" y="0" width="920" height="268" fill="transparent"/></svg>`;document.getElementById('chart-tip').innerHTML=`<span>${val.date}</span><b><i class="small-square green"></i> EV ${mode==='share'?pct(val.evShare):fmt(val.ev)}</b><b><i class="small-square mid"></i> Hybrid ${mode==='share'?pct(val.hybridShare):fmt(val.hybrid)}</b>`;document.querySelector('#chart-hot').onmousemove=e=>{const box=e.currentTarget.getBoundingClientRect();hover=Math.max(0,Math.min(d.length-1,Math.round((e.clientX-box.left)/box.width*(d.length-1))));graph()};document.querySelector('#chart-hot').onmouseleave=()=>{hover=null;graph()};}
function svgMap(){
const p=Object.values(GEO.paths).flat().map(x=>`<path d="${x}" class="map-country"/>`).join('');
const text=(t,cls,x,y)=>`<text x="${x}" y="${y}" class="${cls}">${t}</text>`;
const markers=GEO.markers.map(r=>`<g class="map-marker" role="button" tabindex="0" data-city="${r.name}">
  ${r.name===city?`<circle cx="${r.x}" cy="${r.y}" r="14" class="marker-glow"/>`:''}
  <circle cx="${r.x}" cy="${r.y}" r="${r.name===city?7:5.3}" class="${r.name===city?'marker-active':'marker-idle'}"/>
  <circle cx="${r.x}" cy="${r.y}" r="1.7" fill="${r.name===city?'#171918':'#fff'}"/>
  <text x="${r.x+12}" y="${r.y-9}" class="marker-label ${r.name===city?'active':''}">${r.name}</text>
</g>`).join('');
const selected=GEO.markers.find(r=>r.name===city)||GEO.markers[0];
document.getElementById('svg-map').innerHTML=`
  <div class="geo-map-topbar"><span class="geo-map-eyebrow"><span class="geo-map-live"></span>MALAYSIA / GEOGRAPHIC BASEMAP</span><span class="geo-map-topright">REFERENCE LOCATIONS · 05</span></div>
  <svg class="malaysia-map-art" viewBox="0 0 685 320" role="img" aria-label="Malaysia reference map with selectable cities">
   <defs><pattern id="mapFineGrid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0 H0 V22" stroke="currentColor" stroke-width=".35" fill="none" opacity=".22"/></pattern><pattern id="landTexture" width="7" height="7" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".55" fill="currentColor" opacity=".09"/></pattern><filter id="mapAmbient"><feDropShadow dx="0" dy="5" stdDeviation="6" flood-color="#7c887a" flood-opacity=".10"/></filter></defs>
   <rect width="685" height="320" fill="url(#mapFineGrid)" class="map-grid-background"/>
   <g transform="translate(${342.5*(1-mapZoom)} ${160*(1-mapZoom)}) scale(${mapZoom})" style="transition:transform .35s ease">
   <path d="M0 80H685 M0 180H685 M130 0V320 M355 0V320 M550 0V320" stroke="currentColor" stroke-width=".6" stroke-dasharray="2 7" opacity=".15"/>
   <g filter="url(#mapAmbient)">${p}</g><g style="pointer-events:none">${Object.values(GEO.paths).flat().map(x=>`<path d="${x}" fill="url(#landTexture)" opacity=".55"/>`).join('')}</g>
   ${text('PENINSULAR','map-region',80,36)}${text('BORNEO','map-region',439,36)}${markers}
   </g></svg>
  <div class="geo-map-city-card"><div class="geo-map-city-icon">${icon('info',18)}</div><div><span>LOCATION FOCUS</span><b>${selected.name}</b><small>Reference marker · no state adoption data</small></div></div>
  <div class="geo-map-controls"><button id="map-zoom-in" aria-label="Zoom in" title="Zoom in"><span>+</span></button><button id="map-zoom-out" aria-label="Zoom out" title="Zoom out"><span>−</span></button><button id="map-zoom-reset" aria-label="Reset zoom" title="Reset">⌗</button></div>
  <div class="map-disclaimer">${icon('info',13)}<span>National outlines and reference cities only. State EV data not yet connected.</span></div>`;
document.querySelectorAll('[data-city]').forEach(b=>{b.onclick=()=>{city=b.dataset.city;svgMap()};b.onkeydown=e=>{if(e.key==='Enter'){city=b.dataset.city;svgMap()}}});
document.getElementById('map-zoom-in').onclick=()=>{mapZoom=Math.min(2.4,mapZoom+.3);svgMap()};
document.getElementById('map-zoom-out').onclick=()=>{mapZoom=Math.max(1,mapZoom-.3);svgMap()};
document.getElementById('map-zoom-reset').onclick=()=>{mapZoom=1;svgMap()};
}
function donut(){const parts=[last.evShare,last.hybridShare,100-last.electrifiedShare];let offset=0;const s=parts.map((v,i)=>{const out=`<circle cx="85" cy="85" r="64" fill="none" stroke="${['#a9f820','#747a79','#dfe0dc'][i]}" stroke-width="20" stroke-dasharray="${v/100*402.12} ${402.12-v/100*402.12}" stroke-dashoffset="${-offset/100*402.12}" transform="rotate(-90 85 85)"/>`;offset+=v;return out}).join('');document.getElementById('mix-donut').innerHTML=`<svg viewBox="0 0 170 170">${s}<text x="85" y="77" text-anchor="middle" class="donut-label">xEV SHARE</text><text x="85" y="103" text-anchor="middle" font-weight="600" font-size="26" class="donut-num">${pct(last.electrifiedShare,1)}</text></svg>`}
function forecastSpark(){let f=forecast.filter((_,i)=>i%3===0),pts=f.map((d,i)=>[4+i/(f.length-1)*321,70-(d.value-45)/40*60]);let path=pts.map(([x,y],i)=>(i?'L':'M')+x.toFixed(2)+','+y.toFixed(2)).join(' ');document.getElementById('spark-graph').innerHTML=`<svg viewBox="0 0 330 82" preserveAspectRatio="none"><path d="${path} L325,78 L4,78Z" fill="#aeff28" opacity=".12"/><path d="${path}" stroke="#aeff28" stroke-width="2.5" fill="none"/><line x1="4" y1="77" x2="326" y2="77" stroke="#454a44"/></svg>`}
function toast(t){const x=document.getElementById('toast');x.textContent=t;x.style.display='block';setTimeout(()=>x.style.display='none',3500)}
function download(){const keys=['date','total','ev','hybrid','petrol','evShare','hybridShare','electrifiedShare','evOfElectrified'];let csv=[keys.join(','),...months.map(r=>keys.map(k=>r[k]).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='myev_jpj_car_market.csv';a.click()}
document.addEventListener('DOMContentLoaded',()=>{graph();svgMap();donut();forecastSpark();document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('picked',x===b));graph()}));document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{range=b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('picked',x===b));graph()}));document.getElementById('dark-toggle').onclick=()=>document.querySelector('.app').classList.toggle('theme-dark');document.getElementById('mobile-menu').onclick=()=>{let el=document.getElementById('mobile-nav');el.style.display=el.style.display==='none'?'grid':'none'};document.getElementById('data-export').onclick=download;document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>toast('Full multi-page navigation is available in the included React + Vite project.'))});
'''.replace('__DATA__',json.dumps(data,separators=(',',':'))).replace('__GEO__',json.dumps(geo,separators=(',',':')))
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>MyEV — Overview (Standalone Preview)</title><style>'''+css+'''</style></head><body><div class="app theme-light"><header class="site-header"><div class="header-inner"><button class="brand"><span class="brand-mark"><span class="brand-mark-inner"></span></span><span class="brand-type">MyEV<span class="brand-dot">.</span></span></button><nav class="nav-main"><button class="nav-item active">Overview</button><button class="nav-item" data-preview>Markets</button><button class="nav-item" data-preview>Geospatial⌄</button><button class="nav-item" data-preview>Intelligence⌄</button><button class="nav-item" data-preview>Sustainability</button><button class="nav-item" data-preview>Reports</button></nav><div class="nav-actions"><span class="live-data"><i></i>JPJ DATA · AUG '26</span><button class="icon-btn" id="dark-toggle" aria-label="Toggle theme">☾</button><button class="header-export" id="data-export">↓ &nbsp; Export data</button><button class="mobile-toggle icon-btn" id="mobile-menu" aria-label="Open menu">☰</button></div></div><div class="mobile-nav" id="mobile-nav" style="display:none"><button data-preview>Overview ↗</button><button data-preview>Markets ↗</button><button data-preview>Geospatial ↗</button><button data-preview>Forecasting ↗</button><button data-preview>Policy ↗</button><button data-preview>Sustainability ↗</button></div></header><main class="main-content"><div class="page page-overview"><section class="hero"><div class="hero-copy"><div class="kicker"><span class="kicker-mark"></span>MALAYSIA · MOBILITY INTELLIGENCE</div><h1>The transition<br><span>in motion</span><span class="hero-punct">.</span></h1><p>A clearer view of Malaysia's shift to electric mobility. Explore the market, understand the policy, and anticipate what comes next.</p><div class="hero-actions"><button class="button-dark" data-preview>Explore the market ↗</button><button class="button-ghost" data-preview>Explore the map →</button></div></div><div class="hero-stamp"><span>INSIGHT EDITION</span><strong>26<span>/</span>08</strong><span>BASED ON OFFICIAL JPJ RECORDS</span></div></section><div class="meta-ribbon"><span><span class="ribbon-dot"></span>Data coverage <strong>Jan 2000 – Aug 2026</strong></span><span>✓ Computed from the uploaded JPJ CSV</span><span class="ribbon-end">Updated from uploaded source ↗</span></div><section class="kpi-strip"><div class="metric"><span class="metric-label">EV REGISTRATIONS</span><div class="metric-num">8,834</div><div class="metric-sub"><span class="positive">↗ +155.2% YoY</span> · Aug 2026</div></div><div class="metric"><span class="metric-label">HYBRID REGISTRATIONS</span><div class="metric-num">4,964</div><div class="metric-sub">Passenger cars · Aug 2026</div></div><div class="metric"><span class="metric-label">EV MARKET SHARE</span><div class="metric-num">11.41%</div><div class="metric-sub">EV / all car registrations</div></div><div class="metric"><span class="metric-label">TOTAL ELECTRIFICATION</span><div class="metric-num metric-accent">17.83%</div><div class="metric-sub">EV + Hybrid / all cars</div></div></section><section class="analysis-grid"><div class="panel chart-panel"><div class="panel-heading"><div><span class="eyebrow">01 / MARKET SIGNAL</span><h3>Adoption, in perspective<span class="dot-lime">.</span></h3><p>Monthly passenger car registrations · Jan 2022 – Aug 2026</p></div><span class="data-tag">JPJ OPEN DATA</span></div><div class="viz-wrap"><div class="chart-controls"><div class="toggle-group"><button data-mode="registrations" class="picked">Volume</button><button data-mode="share">Market share</button></div><div class="range-group"><button data-range="1Y">1Y</button><button data-range="3Y" class="picked">3Y</button><button data-range="ALL">ALL</button></div></div><div class="linechart-container"><div id="real-chart" style="width:100%;height:100%"></div><div class="chart-tooltip" id="chart-tip"></div></div></div><div class="panel-foot"><span><span class="data-led lime"></span>Electric</span><span><span class="data-led slate"></span>Hybrid</span><span class="panel-foot-right">Source: JPJ · registrations by fuel</span></div></div><div class="panel map-panel"><div class="panel-heading"><div><span class="eyebrow">02 / GEOGRAPHIC LENS</span><h3>Across Malaysia<span class="dot-lime">.</span></h3><p>An interactive national map experience</p></div><button class="small-round" data-preview>↗</button></div><div class="malaysia-map compact" id="svg-map"></div><div class="map-bottom"><div><span class="map-legend-dot"></span>NATIONAL GEOGRAPHY PREVIEW</div><button class="inline-underlined" data-preview>Open explorer →</button></div></div></section><section class="module-section"><div class="section-header"><div><span class="eyebrow">A CLOSER LOOK</span><h2>The intelligence behind the shift.</h2><p>Every signal tells a different part of the story.</p></div><button class="text-link" data-preview>View all modules ↗</button></div><div class="feature-grid"><div class="feature-card forecast-feature"><div class="feature-top"><span class="eyebrow">03 / FORWARD VIEW</span><span class="pill-dark">M9 · RESEARCH MODEL</span></div><div class="forecast-number">59.13<small>%</small></div><p class="forecast-desc">Projected EV share within EV + Hybrid by Dec 2030.</p><div class="mini-forecast" id="spark-graph"></div><div class="feature-bottom"><span>95% conditional PI: 47.36% – 70.90%</span><button class="round-arrow" data-preview>↗</button></div></div><div class="feature-card mix-feature"><div class="feature-top"><span class="eyebrow">04 / FUEL COMPOSITION</span><span class="year-pill">AUG 2026</span></div><h3>A shifting<br>powertrain mix.</h3><div class="mix-visual"><div class="donut-wrap" id="mix-donut"></div><div class="mix-legend"><div><i class="small-square green"></i><span>Electric</span><b>11.4%</b></div><div><i class="small-square mid"></i><span>Hybrid</span><b>6.4%</b></div><div><i class="small-square grey"></i><span>All others</span><b>82.2%</b></div></div></div><div class="feature-bottom"><span>Share of passenger car registrations</span><button class="round-arrow" data-preview>↗</button></div></div><div class="feature-card policy-feature"><div class="feature-top"><span class="eyebrow">05 / POLICY CONTEXT</span><span class="year-pill">EVENT STUDY</span></div><h3>Numbers don't<br>move alone.</h3><div class="policy-list"><div><i class="event-dot"></i><div><b>JAN 2022</b><span>Budget 2022 EV incentives begin</span></div></div><div><i class="event-dot active"></i><div><b>DEC 2025</b><span>CBU EV duty exemption expires</span></div></div><div><i class="event-dot"></i><div><b>2026</b><span>Post-exemption regime evaluation</span></div></div></div><div class="feature-bottom"><span>Associations ≠ causal attribution</span><button class="round-arrow" data-preview>↗</button></div></div></div></section><div class="closing-banner"><div><span class="eyebrow">BUILT FOR BETTER DECISIONS</span><h2>Go beyond the chart<span>.</span></h2><p>Explore market signals, forecasting uncertainty, policy context and the path to a more sustainable mobility future.</p></div><button class="banner-btn" data-preview>Launch intelligence lab ↗</button></div></div></main><footer class="footer"><div class="footer-left"><span class="footer-brand">MyEV.</span><span>Malaysia Electric Mobility Intelligence</span></div><div class="footer-right"><span>Data: JPJ / data.gov.my · Through Aug 2026</span><span>Independent research prototype · Not an official JPJ service</span></div></footer><div id="toast" class="toast" style="display:none"></div></div><script>'''+script+'''</script></body></html>'''
(ROOT/'preview/VOLTERRA_Standalone_Preview.html').write_text(html)
print('Preview HTML bytes',len(html))
